/**
 * Vocabulary for labeling analytical/AI output so a deterministic rule, a plain
 * statistical count, and text generated by an external model are never
 * presented the same way. Every generated response should carry one of these
 * types plus provider/model/version, generation time, uncertainty, and review
 * status -- see PDF item 26 ("Add analytical and AI governance").
 */
export const GENERATION_TYPES = Object.freeze([
  'deterministic-rule',
  'statistical',
  'predictive-model',
  'machine-learning',
  'generative-ai',
]);

export const REVIEW_STATUSES = Object.freeze(['unreviewed', 'human-reviewed', 'auto-accepted']);

/**
 * Builds the governance envelope merged into a generated API response or
 * stored record. `generationType` is required and validated -- callers must
 * make an explicit choice rather than defaulting to something that could read
 * as "AI" for an ordinary rule or count.
 */
export function describeGeneration({ generationType, provider = 'local', model = '', modelVersion = '', generatedAt = new Date().toISOString(), inputRefs = [], uncertainty = 'unknown', reviewStatus = 'unreviewed' } = {}) {
  if (!GENERATION_TYPES.includes(generationType)) {
    throw new Error(`generationType must be one of: ${GENERATION_TYPES.join(', ')}.`);
  }
  if (!REVIEW_STATUSES.includes(reviewStatus)) {
    throw new Error(`reviewStatus must be one of: ${REVIEW_STATUSES.join(', ')}.`);
  }
  return {
    generationType,
    provider: String(provider || 'local').trim() || 'local',
    model: String(model || '').trim(),
    modelVersion: String(modelVersion || '').trim(),
    generatedAt,
    inputRefs: Array.isArray(inputRefs) ? inputRefs.filter(Boolean) : [],
    uncertainty,
    reviewStatus,
  };
}

/** Merges a governance envelope into a response payload without overwriting caller-supplied fields (e.g. `summary`, `model`). */
export function annotateGeneration(payload, options) {
  return { ...describeGeneration(options), ...payload };
}
